def parse_requirement(dep: str, found: Optional[str]) ->PythonSpecification:
    from dparse.dependencies import parse as parse_dep
    parsed = parse_dep(dep, found=found)
    return PythonSpecification(parsed.line, found=found)


def read_dependencies(fh, resolve: bool=True) ->Generator[PythonDependency,
    None, None]:
    yield from read_requirements(fh, resolve=resolve)
